// hv4d/todd_coxeter.hpp
// Todd-Coxeter coset enumeration over a finitely presented (Coxeter) group.
// Used to enumerate vertices / edges / faces / cells of the regular 4-polytopes
// from their Schlafli symbol {p, q, r}.
#pragma once

#include <functional>
#include <vector>

namespace hv4d {
namespace todd_coxeter {

using Relation = std::vector<int>;
using Table = std::vector<std::vector<int>>;

// Enumerate the cosets of the subgroup generated by `sub_gens` in the group
// <0..num_gens-1 | relations>.  Returns table[coset][generator] -> coset.
// Throws std::runtime_error if the enumeration is inconsistent.
Table coset_table(int num_gens, const std::vector<Relation>& relations, const std::vector<int>& sub_gens);

// Breadth-first walk over the coset graph.  `initial` is the value for coset
// `start`; every other coset's value is `f(value_of_parent, generator)`.
template <typename T, typename F>
std::vector<T> table_bfs_fold(const Table& table, int start, const T& initial, F&& f) {
    std::vector<T> result(table.size(), initial);
    std::vector<char> seen(table.size(), 0);
    std::vector<int> queue;
    queue.reserve(table.size());
    queue.push_back(start);
    seen[start] = 1;
    for (size_t head = 0; head < queue.size(); ++head) {
        const int top = queue[head];
        for (size_t g = 0; g < table[top].size(); ++g) {
            const int next = table[top][g];
            if (seen[next]) continue;
            result[next] = f(result[top], static_cast<int>(g));
            queue.push_back(next);
            seen[next] = 1;
        }
    }
    return result;
}

}  // namespace todd_coxeter
}  // namespace hv4d
